const FX_DEFINITION_BY_TYPE = new Map(FX_DEFINITIONS_V1.map((definition) => [definition.slotType, definition]));
const VALID_LFO_RATE_MODES = new Set(["hz", "sync"]);
const VALID_LFO_SYNC_DIVISIONS = new Set([
	"whole",
	"half",
	"quarter",
	"eighth",
	"sixteenth",
	"thirtySecond",
	"dottedQuarter",
	"dottedEighth",
	"quarterTriplet",
	"eighthTriplet"
]);
function isFiniteNumber(value) {
	return typeof value === "number" && Number.isFinite(value);
}
function coerceBoolean(value, fallback) {
	if (typeof value === "boolean") return value;
	if (typeof value === "number") return value !== 0;
	if (typeof value === "string") {
		if (value === "true") return true;
		if (value === "false") return false;
	}
	return fallback;
}
function normalizeFxParamKey(type, controlId) {
	if (type === "phaseMod") {
		if (controlId === "intPmAmount") return "amount";
		if (controlId === "intPmRatio") return "ratio";
	}
	return controlId;
}
function buildDefaultControlValue(type, control) {
	const key = normalizeFxParamKey(type, control.id);
	if (key === "timeMode" || key === "rateMode") return "hz";
	if (key === "syncDivision") return "quarter";
	if (key === "tapeMode" || key === "pmPre" || control.kind === "toggle") return coerceBoolean(control.defaultF32, false);
	if (control.options.length > 0) return control.options[0]?.value ?? control.defaultF32 ?? 0;
	return control.defaultF32 ?? 0;
}
function sanitizeControlValue(type, control, value, fallback) {
	const key = normalizeFxParamKey(type, control.id);
	if (key === "timeMode" || key === "rateMode") return VALID_LFO_RATE_MODES.has(value) ? value : fallback ?? "hz";
	if (key === "syncDivision") return VALID_LFO_SYNC_DIVISIONS.has(value) ? value : fallback ?? "quarter";
	if (key === "tapeMode" || key === "pmPre" || control.kind === "toggle") return coerceBoolean(value, Boolean(fallback));
	if (control.options.length > 0) return control.options.some((option) => option.value === value) ? value : fallback ?? control.options[0]?.value ?? 0;
	return isFiniteNumber(value) ? value : fallback ?? control.defaultF32 ?? 0;
}
function createDefaultFxSlotConfig(type) {
	if (type === "empty") return { type: "empty" };
	const definition = FX_DEFINITION_BY_TYPE.get(type);
	if (!definition) return { type: "empty" };
	return {
		type,
		params: definition.controls.reduce((accumulator, control) => {
			const key = normalizeFxParamKey(type, control.id);
			accumulator[key] = buildDefaultControlValue(type, control);
			return accumulator;
		}, { enabled: true })
	};
}
function sanitizeFxSlotConfig(slot) {
	if (slot.type === "empty") return slot;
	const defaults = createDefaultFxSlotConfig(slot.type);
	const definition = FX_DEFINITION_BY_TYPE.get(slot.type);
	if (!definition) return defaults;
	const rawParams = slot.params;
	const defaultParams = defaults.params;
	const sanitizedParams = definition.controls.reduce((accumulator, control) => {
		const key = normalizeFxParamKey(slot.type, control.id);
		const rawValue = rawParams[key] ?? rawParams[control.id];
		accumulator[key] = sanitizeControlValue(slot.type, control, rawValue, defaultParams[key]);
		return accumulator;
	}, { enabled: coerceBoolean(rawParams.enabled, Boolean(defaultParams.enabled)) });
	return {
		type: slot.type,
		params: sanitizedParams
	};
}
function sanitizeFxSlots(fxSlots) {
	if (!fxSlots) return fxSlots;
	return fxSlots.map((slot) => sanitizeFxSlotConfig(slot));
}
function sanitizeSynthParamsForEngine(params) {
	return {
		...params,
		fxSlots: sanitizeFxSlots(params.fxSlots)
	};
}
