				smoothLevel *= .9;
				if (lastPublishedLevel < 0 || Math.abs(lastPublishedLevel - smoothLevel) > .01) {
					onAudioLevelChange(smoothLevel);
					lastPublishedLevel = smoothLevel;
				}
