//#region src/features/synth/hooks/useSynthParamsToWorklet.ts
function useSynthParamsToWorklet({ workletNodeRef, paramsRef, effectivePitchHz, gatherState, voiceLimit }) {
	const adapter = useMemo(() => createWorkletSynthEngineAdapter({
		workletNodeRef,
		paramsRef
	}), [workletNodeRef, paramsRef]);
	useEffect(() => {
		const controller = new SynthEngineController(adapter);
		controller.connect();
		return () => controller.dispose();
	}, [adapter]);
	useEffect(() => {
		const sync = () => {
			const snapshot = createSynthEngineSnapshot({
				gatherState,
				effectivePitchHz
			});
			adapter.sync(snapshot);
		};
		sync();
		return useSynthStore.subscribe(sync);
	}, [
		adapter,
		gatherState,
		effectivePitchHz
	]);
	const voiceLimitRef = useRef();
	useEffect(() => {
		if (voiceLimit === voiceLimitRef.current || voiceLimit === void 0) return;
		if (!workletNodeRef.current) return;
		workletNodeRef.current.port.postMessage({
			type: "setVoiceLimit",
			limit: voiceLimit
		});
		voiceLimitRef.current = voiceLimit;
	}, [voiceLimit, workletNodeRef]);
	useEffect(() => {
		return subscribeApplyModulePreset((request) => {
			if (!workletNodeRef.current) return;
			workletNodeRef.current.port.postMessage({
				type: "applyModulePreset",
				module: request.module,
				preset: request.preset,
				patch: request.patch
			});
		});
	}, [workletNodeRef]);
}
