	const repairLibrary = useCallback(() => runLibraryRecovery(repository.repairLibrary), [repository.repairLibrary, runLibraryRecovery]);
	const rebuildLibrary = useCallback(() => runLibraryRecovery(repository.rebuildLibrary), [repository.rebuildLibrary, runLibraryRecovery]);
